import java.util.*;

public class AutocompleteTrie {
    private final TrieNode root = new TrieNode();

    private static class TrieNode {
        private final Map<Character, TrieNode> children = new HashMap<>();
        private boolean isEndOfWord;
        private final List<String> topCompletions = new ArrayList<>();

        public void addCompletion(String word, int limit) {
            if (!topCompletions.contains(word)) {
                topCompletions.add(word);
                topCompletions.sort(Comparator.naturalOrder());
                if (topCompletions.size() > limit) {
                    topCompletions.remove(topCompletions.size() - 1);
                }
            }
        }
    }

    public void insert(String word, int limit) {
        TrieNode current = root;
        for (char ch : word.toCharArray()) {
            current = current.children.computeIfAbsent(ch, c -> new TrieNode());
            current.addCompletion(word, limit);
        }
        current.isEndOfWord = true;
    }

    public List<String> getCompletions(String prefix) {
        TrieNode current = root;
        for (char ch : prefix.toCharArray()) {
            current = current.children.get(ch);
            if (current == null) {
                return Collections.emptyList();
            }
        }
        return current.topCompletions;
    }
}
